449	// --- diff：任一侧归档含非法文本成员都整体失败，不输出局部差异，不能把被
450	// 默认成空字符串的内容判为“无变化” ---
451	
452	func TestDiffStoreRejectsBadRuleTextEitherSide(t *testing.T) {
453		dir := t.TempDir()
454		good := oneDefectFixture()
455		goodID := writeReportWithFreshID(t, dir, good)
456	
457		// 另一侧是另一份合法报告（多一条无说明的通过规则），损坏后落盘；null
458		// 会被洗成 ""，所以损坏归档与合法归档共用同一标识，先留一份干净字节。
459		other := oneDefectFixture()
460		other.Rules = append(other.Rules,
461			ReportRule{ID: "r-extra", Kind: "static", Severity: "info", Invariant: "inv-extra", Version: "9", Status: StatusPass})
462		otherID := writeReportWithFreshID(t, dir, other)
463		cleanOther, err := os.ReadFile(filepath.Join(dir, otherID+".json"))
464		if err != nil {
