574		}
575		after, err := os.ReadFile(path)
576		if err != nil {
577			t.Fatalf("corrupt archive must be kept: %v", err)
578		}
579		if string(after) != string(before) {
580			t.Fatal("failed save must leave the corrupt archive untouched")
581		}
582	}
583	
584	// --- 合法 JSON 文本中的字符串值不受影响：显式字符串的 Unicode 转义写法与
585	// 直接书写读回同一内容 ---
586	
587	func TestLoadReportRuleTextLegalStringUnaffected(t *testing.T) {
588		dir := t.TempDir()
589		id := writeReportWithFreshID(t, dir, oneDefectFixture())
590		loaded, err := LoadReport(dir, id)
