78	// assertRuleTextCorruptFailure asserts the full CLI failure contract for a
79	// non-string formal rule text member.
80	func assertRuleTextCorruptFailure(t *testing.T, stdout, stderr string, code int, id, position, rule, field string) {
81		t.Helper()
82		if code == 0 {
83			t.Fatal("an archive with a non-string rule text member must exit non-zero")
84		}
85		if !strings.Contains(stderr, "corrupt") {
86			t.Fatalf("stderr must classify the archive as corrupt:\n%s", stderr)
87		}
88		if !strings.Contains(stderr, id) {
89			t.Fatalf("stderr must name the report id %q:\n%s", id, stderr)
90		}
91		if !strings.Contains(stderr, position) {
92			t.Fatalf("stderr must name the rule array position %q:\n%s", position, stderr)
93		}
94		if rule != "" && !strings.Contains(stderr, rule) {
95			t.Fatalf("stderr must name the offending rule %q:\n%s", rule, stderr)
96		}
97		if !strings.Contains(stderr, field+" must be a string") {
98			t.Fatalf("stderr must state %s must be a string:\n%s", field, stderr)
99		}
100		if stdout != "" {
101			t.Fatalf("rejected read must print nothing to stdout, got:\n%s", stdout)
102		}
103	}
