31	// injectArchiveDuplicate reads the archive named by id, applies the textual
32	// replacement once, and writes it back. All replacements repeat a member
33	// while leaving the last value identical to the legal one.
34	func injectArchiveDuplicate(t *testing.T, store, id, old, new string) {
35		t.Helper()
