154		stdout, stderr, code := runCLIReport(t, bin, store, id)
155		assertDupFailure(t, stdout, stderr, code, id, `"reportId"`, "the top-level object")
156	}
157	
158	// --- report：未知字段的嵌套对象重复成员同样拒绝 ---
159	
160	func TestCLIReportDuplicateNestedUnknownFieldRejected(t *testing.T) {
161		bin := auditBinary(t)
162		work := t.TempDir()
163		store := filepath.Join(work, "reports")
164		id := auditOneReport(t, bin, work, store)
165		injectArchiveDuplicate(t, store, id,
166			`{"reportId"`,
167			`{"mystery":{"a":1,"a":2},"reportId"`)
168	
169		stdout, stderr, code := runCLIReport(t, bin, store, id)
170		assertDupFailure(t, stdout, stderr, code, id, `"a"`, ".mystery")
171	}
172	
173	// --- 错误分类不变：重复成员是损坏；不存在与标识不合法仍是各自的含义 ---
174	
175	func TestCLIReportDuplicateDoesNotMaskOtherErrors(t *testing.T) {
176		bin := auditBinary(t)
177		work := t.TempDir()
178		store := filepath.Join(work, "reports")
179		id := auditOneReport(t, bin, work, store)
180		injectArchiveDuplicate(t, store, id,
181			`"status":"`+contractsentinel.StatusPass+`"`,
