133	// runCLIReport 在真实进程上运行 report，返回 stdout、stderr 与退出码。
134	func runCLIReport(t *testing.T, bin, store, id string) (string, string, int) {
135		t.Helper()
136		cmd := exec.Command(bin, "report", "--store", store, "--id", id)
137		var stdout, stderr bytes.Buffer
138		cmd.Stdout = &stdout
139		cmd.Stderr = &stderr
140		err := cmd.Run()
141		if err == nil {
142			return stdout.String(), stderr.String(), 0
143		}
144		if exitErr, ok := err.(*exec.ExitError); ok {
145			return stdout.String(), stderr.String(), exitErr.ExitCode()
146		}
147		t.Fatalf("failed to start report: %v", err)
148		return "", "", 0
149	}
