77				new:  `"StAtus":"` + StatusPass + `","status":"` + StatusDefect + `"`,
78			},
79		} {
80			t.Run(tc.name, func(t *testing.T) {
81				dir := t.TempDir()
82				id := writeDupArchiveText(t, dir, oneDefectFixture(), dupOnce(tc.old, tc.new))
83	
84				loaded, err := LoadReport(dir, id)
85				if err != nil {
